param([Parameter(Mandatory=$true)][string]$RunDir,[string]$Root="C:\pinchbench-grok-build",[string]$Python="",[string]$SkillDir="",[string]$ProxyUrl="http://127.0.0.1:10090",[string]$AdapterUrl="http://127.0.0.1:8767")
$ErrorActionPreference="Stop";. (Join-Path $PSScriptRoot "common_grok_build_runner.ps1");Set-GrokBenchmarkEnvironment -Root $Root -ProxyUrl $ProxyUrl;Assert-OpenRouterKey;$null=Assert-GrokSearchAdapter -AdapterUrl $AdapterUrl;$p=Resolve-GrokRunnerPaths -Root $Root -Python $Python -SkillDir $SkillDir
$cfg=Get-Content (Join-Path $RunDir "run_config.json") -Raw -Encoding UTF8|ConvertFrom-Json;$stamp=Get-Date -Format "yyyyMMdd-HHmmss";$out=Join-Path $p.Logs "resume-$stamp.stdout.txt";$err=Join-Path $p.Logs "resume-$stamp.stderr.txt"
$args=@("-X","utf8",$p.Runner,"--skill-dir",$p.Skill,"--grok-build-cli",$p.Grok,"--grok-build-home",$p.Home,"--adapter-url",$AdapterUrl,"--suite",([string]$cfg.suite),"--judge-model",([string]$cfg.judge_model),"--timeout-multiplier",([string]$cfg.timeout_multiplier),"--network-timeout",([string]$cfg.network_timeout),"--judge-timeout","300","--results-dir",$p.Runs,"--resume-run",$RunDir,"--keep-workspaces","--verbose")
$proc=Start-Process -FilePath $p.Python -ArgumentList $args -WorkingDirectory $Root -RedirectStandardOutput $out -RedirectStandardError $err -NoNewWindow -Wait -PassThru;Show-LoggedProcessResult $proc $out $err 300;if($proc.ExitCode-ne 0){throw "Resume failed with exit code $($proc.ExitCode)"};Write-Host "PASS: run resumed and finalized." -ForegroundColor Green
